using System; using System.Drawing; using System.Drawing.Imaging; using System.Collections.Generic;
public class BrandWeb {
public static Bitmap Extract(string path,int threshold) { var original=new Bitmap(path); var b=new Bitmap(original.Width,original.Height,PixelFormat.Format32bppArgb); using(var g=Graphics.FromImage(b)){g.DrawImageUnscaled(original,0,0);} int w=b.Width,h=b.Height; var seen=new bool[w*h]; var q=new Queue<int>(); for(int x=0;x<w;x++){q.Enqueue(x);q.Enqueue((h-1)*w+x);} for(int y=0;y<h;y++){q.Enqueue(y*w);q.Enqueue(y*w+w-1);} while(q.Count>0){int i=q.Dequeue();if(seen[i])continue;seen[i]=true;int x=i%w,y=i/w;var c=b.GetPixel(x,y);if(Math.Max(c.R,Math.Max(c.G,c.B))>threshold)continue;b.SetPixel(x,y,Color.FromArgb(0,c.R,c.G,c.B));if(x>0)q.Enqueue(i-1);if(x<w-1)q.Enqueue(i+1);if(y>0)q.Enqueue(i-w);if(y<h-1)q.Enqueue(i+w);}return b; }
public static Bitmap Contour(string path){var o=new Bitmap(path);var b=new Bitmap(o.Width,o.Height,PixelFormat.Format32bppArgb);var mask=new Bitmap(o.Width,o.Height,PixelFormat.Format32bppArgb);using(var p=new System.Drawing.Drawing2D.GraphicsPath()){p.AddBezier(90,520,45,470,40,400,55,320);p.AddBezier(55,320,65,230,110,170,190,125);p.AddBezier(190,125,290,75,370,80,440,105);p.AddBezier(440,105,500,135,550,230,647,336);p.AddBezier(647,336,603,268,577,174,616,97);p.AddBezier(616,97,640,63,658,50,668,50);p.AddBezier(668,50,695,51,733,64,765,100);p.AddBezier(765,100,810,160,845,215,860,290);p.AddBezier(860,290,885,345,875,415,842,455);p.AddBezier(842,455,800,505,733,540,660,550);p.AddBezier(660,550,565,555,465,505,390,442);p.AddBezier(390,442,285,355,210,334,166,368);p.AddBezier(166,368,132,410,118,465,112,520);p.CloseFigure();using(var g=Graphics.FromImage(mask)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.FillPath(Brushes.White,p);g.DrawPath(new Pen(Color.White,4),p);}}for(int y=0;y<o.Height;y++)for(int x=0;x<o.Width;x++){var c=o.GetPixel(x,y);var a=mask.GetPixel(x,y).A;b.SetPixel(x,y,Color.FromArgb(a,c.R,c.G,c.B));}return b;}
public static void Run(string src,string dest){var s=Contour(src+"/nalyvon-symbol-oficial.png");var t=Extract(src+"/nalyvon-wordmark-oficial.png",20);s.Save(dest+"/symbol.png",ImageFormat.Png);t.Save(dest+"/wordmark.png",ImageFormat.Png);var l=new Bitmap(1480,320);using(var g=Graphics.FromImage(l)){g.Clear(Color.Transparent);g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(s,20,42,390,226);g.DrawImage(t,458,110,990,110);}l.Save(dest+"/lockup.png",ImageFormat.Png);var f=new Bitmap(256,256);using(var g=Graphics.FromImage(f)){g.Clear(Color.FromArgb(11,12,14));g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(s,12,61,232,135);}f.Save(dest+"/favicon.png",ImageFormat.Png);}
}
